steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query {
    issues(first: 50, query: \"Website Redesign pagination\") {
      nodes {
        id
        identifier
        title
        description
        priority
        priorityName
        completedAt
        workflowState {
          name
        }
        team {
          name
        }
        project {
          name
        }
      }
    }
  }"
}'
